### Python

```python
import sys

# 构建到 maxN 的最小质因子表
def build_spf(maxN: int):
    spf = [0] * (maxN + 1)
    if maxN >= 1:
        spf[1] = 1
    for i in range(2, maxN + 1):
        if spf[i] == 0:
            for j in range(i, maxN + 1, i):
                if spf[j] == 0:
                    spf[j] = i
    return spf

# 计算平方因子核 k(x)：质因子中次数为奇数的乘积
def squarefree_kernel(x: int, spf):
    res = 1
    while x > 1:
        p = spf[x]
        parity = 0
        while x % p == 0:
            x //= p
            parity ^= 1   # 只关心奇偶性
        if parity:
            res *= p
    return res

def main():
    data = list(map(int, sys.stdin.read().strip().split()))
    if not data:
        return
    it = iter(data)
    T = next(it)
    ns = [next(it) for _ in range(T)]
    maxN = max(ns) if ns else 0
    spf = build_spf(maxN)

    out_lines = []
    for n in ns:
        pairs = []
        for i in range(1, n + 1):
            k = squarefree_kernel(i, spf)
            pairs.append((k, i))
        # 按平方因子核排序，核相同时按数值排序（顺序无所谓）
        pairs.sort()
        out_lines.append(' '.join(str(b) for _, b in pairs))
    sys.stdout.write('\n'.join(out_lines))

if __name__ == "__main__":
    main()
```

