```java
import java.io.*;
import java.util.*;

public class Main {
    // 快速读入
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;
        FastScanner(InputStream is) { in = is; }
        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }
        int nextInt() throws IOException {
            int c, sgn = 1, x = 0;
            do { c = read(); } while (c <= 32);
            if (c == '-') { sgn = -1; c = read(); }
            for (; c > 32; c = read()) x = x * 10 + (c - '0');
            return x * sgn;
        }
    }

    // 构建到 maxN 的最小质因子表
    static int[] buildSpf(int maxN) {
        int[] spf = new int[maxN + 1];
        if (maxN >= 1) spf[1] = 1;
        for (int i = 2; i <= maxN; i++) {
            if (spf[i] == 0) {
                for (int j = i; j <= maxN; j += i) {
                    if (spf[j] == 0) spf[j] = i;
                }
            }
        }
        return spf;
    }

    // 计算平方因子核 k(x)
    static int squarefreeKernel(int x, int[] spf) {
        int res = 1;
        while (x > 1) {
            int p = spf[x];
            int parity = 0;
            while (x % p == 0) {
                x /= p;
                parity ^= 1;
            }
            if (parity == 1) res *= p;
        }
        return res;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int T = fs.nextInt();
        int[] ns = new int[T];
        int maxN = 0;
        for (int i = 0; i < T; i++) {
            ns[i] = fs.nextInt();
            if (ns[i] > maxN) maxN = ns[i];
        }
        int[] spf = buildSpf(maxN);
        StringBuilder out = new StringBuilder();
        for (int tc = 0; tc < T; tc++) {
            int n = ns[tc];
            int[][] arr = new int[n][2]; // [核, 数值]
            for (int i = 1; i <= n; i++) {
                int k = squarefreeKernel(i, spf);
                arr[i - 1][0] = k;
                arr[i - 1][1] = i;
            }
            // 按核排序，核相同时按数值排序
            Arrays.sort(arr, (a, b) -> {
                if (a[0] != b[0]) return Integer.compare(a[0], b[0]);
                return Integer.compare(a[1], b[1]);
            });
            for (int i = 0; i < n; i++) {
                if (i > 0) out.append(' ');
                out.append(arr[i][1]);
            }
            out.append('\n');
        }
        System.out.print(out.toString());
    }
}
