### C++

```cpp
#include <bits/stdc++.h>
using namespace std;

// 计算到 maxN 的最小质因子表
static vector<int> build_spf(int maxN) {
    vector<int> spf(maxN + 1);
    for (int i = 2; i <= maxN; ++i) {
        if (spf[i] == 0) {
            for (long long j = i; j <= maxN; j += i) {
                if (spf[j] == 0) spf[j] = i;
            }
        }
    }
    spf[0] = 0; spf[1] = 1;
    return spf;
}

// 计算平方因子核 k(x)：质因子中幂次为奇数的乘积
static int squarefree_kernel(int x, const vector<int>& spf) {
    int res = 1;
    while (x > 1) {
        int p = spf[x];
        int parity = 0;
        while (x % p == 0) {
            x /= p;
            parity ^= 1;  // 只关心奇偶
        }
        if (parity) res *= p;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    if (!(cin >> T)) return 0;
    vector<int> ns(T);
    int maxN = 0;
    for (int i = 0; i < T; ++i) {
        cin >> ns[i];
        maxN = max(maxN, ns[i]);
    }

    // 预处理 SPF
    vector<int> spf = build_spf(maxN);

    for (int tc = 0; tc < T; ++tc) {
        int n = ns[tc];
        vector<pair<int, int>> v;
        v.reserve(n);
        for (int i = 1; i <= n; ++i) {
            int k = squarefree_kernel(i, spf);
            v.emplace_back(k, i);
        }
        // 按平方因子核分组，组内顺序任意
        sort(v.begin(), v.end(), [](const auto& a, const auto& b) {
            if (a.first != b.first) return a.first < b.first;
            return a.second < b.second;
        });
        for (int i = 0; i < n; ++i) {
            if (i) cout << ' ';
            cout << v[i].second;
        }
        cout << '\n';
    }
    return 0;
}
